const vocabulary =
  `cancer|patients|treatment|clinical|survival|tumor|breast cancer|immunotherapy|chemotherapy|metastasis|biomarkers|diagnosis|prognosis|radiotherapy|surgery|genetics|mutation|expression|receptor|protein|cell|tissue|blood|immune|inflammation|disease|therapy|response|outcome|risk|cohort|trial|randomized|placebo|control|screening|prevention|mortality|recurrence|progression|resistance|toxicity|safety|efficacy|quality of life|precision medicine|genomics|transcriptomics|proteomics|metabolomics|epigenetics|methylation|microRNA|DNA|RNA|sequencing|pathway|signaling|apoptosis|proliferation|differentiation|angiogenesis|microenvironment|lymphocytes|macrophages|neutrophils|cytokines|interleukin|antibody|vaccine|infection|viral|bacterial|microbiome|gut|lung|liver|kidney|brain|heart|bone|muscle|skin|pancreas|colorectal|prostate|ovarian|gastric|esophageal|leukemia|lymphoma|melanoma|sarcoma|adenocarcinoma|carcinoma|histology|pathology|imaging|magnetic resonance|computed tomography|ultrasound|endoscopy|biopsy|cytology|hematology|anemia|thrombosis|coagulation|diabetes|obesity|hypertension|cardiovascular|neurological|cognitive|depression|anxiety|fatigue|pain|nutrition|exercise|rehabilitation|palliative care|supportive care|patient-reported outcomes|adverse events|dose response|pharmacokinetics|pharmacodynamics|drug interaction|combination therapy|targeted therapy|checkpoint inhibitor|T-cell receptor|B cells|natural killer cells|stem cells|organoids|xenograft|animal model|in vitro|in vivo|machine learning|deep learning|artificial intelligence|predictive model|validation|sensitivity|specificity|positive predictive value|negative predictive value|confidence interval|hazard ratio|odds ratio|relative risk|systematic review|meta-analysis|evidence|guideline|shared decision making|health economics`.split(
    '|',
  );
export const biomedicalWords = vocabulary.slice(0, 150).map((word, index) => ({
  word,
  frequency: Math.ceil(12000 / (index + 1) ** 0.8),
}));
